const AI_TYPES = ['TagForAction', 'AiActivityResponse'];
const since = new Date(Date.now() - 24*60*60*1000);

function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.activityEvents)) return json.data.activityEvents;
  if (json && Array.isArray(json.activityEvents)) return json.activityEvents;
  return [];
}

const events = $input.all().flatMap(asArray).filter((e) => {
  const at = e.at || e.occurredAt;
  return AI_TYPES.includes(e.type) && at && new Date(at) >= since;
});

return [{ json: { count: events.length, events } }];

const body = $input.first().json;
const textBlock = (body.content || []).find((b) => b.type === 'text');
if (!textBlock) throw new Error('Claude response had no text content block.');
return [{ json: { digest: textBlock.text } }];
